?><section class="panel editor"><div class="section-heading"><div><h2><?= e($profile['business_name']) ?></h2><p class="muted">Your verification status</p></div><?= badge($profile['verification_status']) ?></div><?php if($profile['review_note']): ?><div class="notice"><p><?= e($profile['review_note']) ?></p></div><?php endif ?><form method="post" enctype="multipart/form-data" class="form-stack"><?= csrf() ?><input type="hidden" name="action" value="upload-document"><label>Document type<select name="document_type"><?php foreach(requiredDocuments() as $type): ?><option value="<?= e($type) ?>"><?= e($type) ?></option><?php endforeach ?></select></label><label>Business registration or supporting document<input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png" required></label><p class="field-help">PDF, JPEG, or PNG · Up to 5 MB per document · Maximum 10 documents. Documents are only accessible to your account and administrators.</p><button class="button">Submit document</button></form><h3 class="spaced">Submitted documents</h3><?php $documents=rows('SELECT * FROM supplier_documents WHERE supplier_id=? ORDER BY id DESC',[$uid]); if(!$documents) emptyState('No documents submitted','Upload a business document for administrator review.'); foreach($documents as $d): ?><a class="document-row" href="<?= e(url('verification',['document'=>$d['id']])) ?>"><?= icon('list') ?><span><?= e($d['document_type']) ?> · <?= e($d['original_name']) ?><small><?= e($d['created_at']) ?></small></span><span>Download ↓</span></a><?php endforeach ?></section>
<?php break; case 'suppliers':
pageHeading('A NETWORK BUILT ON TRUST','Supplier reviews','Review submitted business documents before approving supplier access.');
$suppliers=rows("SELECT s.*, u.name, u.email FROM suppliers s JOIN users u ON u.id=s.user_id ORDER BY FIELD(s.verification_status,'pending','rejected','verified'),s.user_id DESC");
foreach($suppliers as $s): ?><section class="panel review-card"><div class="section-heading"><div><h2><?= e($s['business_name']) ?></h2><p class="muted"><?= e($s['name']) ?> · <?= e($s['email']) ?></p></div><?= badge($s['verification_status']) ?></div><?php $docs=rows('SELECT * FROM supplier_documents WHERE supplier_id=?',[$s['user_id']]); if(!$docs): ?><p class="muted">No business documents submitted.</p><?php endif; foreach($docs as $d): ?><a class="document-row" href="<?= e(url('suppliers',['document'=>$d['id']])) ?>"><?= icon('list') ?><?= e($d['document_type']) ?> · <?= e($d['original_name']) ?><span>Download ↓</span></a><?php endforeach ?><form method="post" class="review-form"><?= csrf() ?><input type="hidden" name="action" value="verify-supplier"><input type="hidden" name="supplier_id" value="<?= $s['user_id'] ?>"><label>Review note<input name="review_note" maxlength="500" placeholder="Required when rejecting a supplier" value="<?= e($s['review_note']) ?>"></label><button class="button" name="status" value="verified" <?= !$docs?'disabled':'' ?>>Approve supplier</button><button class="button secondary" name="status" value="rejected">Reject</button></form></section><?php endforeach ?>
<?php break; case 'users':
pageHeading('MARKETPLACE ADMINISTRATION','User management','Manage access to the marketplace.');
?><section class="panel table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach(rows('SELECT id,name,email,role,active FROM users ORDER BY id DESC') as $u): ?><tr><td><strong><?= e($u['name']) ?></strong></td><td><?= e($u['email']) ?></td><td><?= e(ucfirst($u['role'])) ?></td><td><?= badge($u['active']?'active':'inactive') ?></td><td><?php if($u['role']!=='administrator'): ?><form method="post" data-confirm="Change access for this account?"><?= csrf() ?><input type="hidden" name="action" value="toggle-user"><input type="hidden" name="user_id" value="<?= $u['id'] ?>"><button class="text-button"><?= $u['active']?'Deactivate':'Activate' ?></button></form><?php else: ?>—<?php endif ?></td></tr><?php endforeach ?></tbody></table></section>
<?php break; case 'reports':
pageHeading('BUSINESS IN FOCUS','Sales reports','Completed order value, with a clear view of your order pipeline.');
$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));
foreach([$from,$to] as $date) { $parsed=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$parsed || $parsed->format('Y-m-d')!==$date) throw new DomainException('Choose valid report dates.'); }
if($from>$to) throw new DomainException('The start date must be before the end date.');
$params=array_merge($orderParams,[$from.' 00:00:00',$to.' 23:59:59']);
$summary=rows("SELECT o.status,COUNT(*) AS n,SUM(total_cents) AS value FROM orders o WHERE $orderScope AND o.created_at BETWEEN ? AND ? GROUP BY o.status",$params);
?><form class="filters" method="get"><input type="hidden" name="page" value="reports"><label>From<input type="date" name="from" value="<?= e($from) ?>" required></label><label>To<input type="date" name="to" value="<?= e($to) ?>" required></label><button class="button">Apply dates</button><button class="button secondary" type="button" data-print>Print report</button></form><section class="panel"><div class="section-heading"><div><h2>Order performance</h2><p class="muted">Grouped by current status, filtered by order creation date.</p></div></div><?php if(!$summary): emptyState('No orders in this period','Choose another date range to review order performance.');else: ?><table><thead><tr><th>Status</th><th>Orders</th><th class="numeric">Order value</th></tr></thead><tbody><?php foreach($summary as $s): ?><tr><td><?= badge($s['status']) ?></td><td><?= (int)$s['n'] ?></td><td class="numeric"><?= money((int)$s['value']) ?></td></tr><?php endforeach ?></tbody></table><?php endif ?></section><p class="field-help">Completed order value is a marketplace activity measure. Digi-Konek does not process payments or provide accounting records.</p>
<?php break; case 'audit':
pageHeading('ACCOUNTABILITY BY DESIGN','Audit trail','A record of account, product, supplier, and order actions.');
?><section class="panel table-scroll"><table><thead><tr><th>When</th><th>Who</th><th>Action</th><th>Detail</th></tr></thead><tbody><?php foreach(rows('SELECT a.*,u.name FROM audit_logs a JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 200') as $a): ?><tr><td><?= e($a['created_at']) ?></td><td><?= e($a['name']) ?></td><td><code><?= e($a['action']) ?></code></td><td><?= e($a['detail']) ?></td></tr><?php endforeach ?></tbody></table></section><p class="field-help">Showing the 200 most recent events. Audit records cannot be edited through the application.</p>
<?php break; case 'notifications':
pageHeading('STAY IN THE LOOP','Your notifications','Updates from your business connections.');
